class Obj {
    int v;
    Obj(int v) { this.v = v; }
}
public class Main {
    public static void main(String[] args) {
        Obj a = new Obj(1), b = new Obj(2), c = new Obj(3);
        Obj[] arr = {a, b, c};
        Obj t = arr[0];
        arr[0] = arr[2];
        arr[2] = t;
        arr[1].v = arr[0].v;
        System.out.print(a.v + "a" + b.v + "b" + c.v);
    }
}

#include <stdio.h>
struct node {
    int p;
    struct node *n;
};
int main() {
    struct node a = {1, NULL}, b = {2, NULL}, c = {3, NULL};
    c.n = &a;
    a.n = &b;
    struct node *head = &c;
    for (struct node *cur = head; cur != NULL; cur = cur->n)
        printf("%d ", cur->p);
    return 0;
}

