#include <stdio.h>
#include <stdlib.h>
struct Node {
    char c;
    struct Node *next;
};
int main() {
    char *str = "BEST";
    struct Node *head = NULL;
    for (int i = 0; str[i] != '\0'; i++) {
        struct Node *n = malloc(sizeof(struct Node));
        n->c = str[i];
        n->next = head;
        head = n;
    }
    for (struct Node *p = head; p != NULL; p = p->next)
        printf("%c", p->c);
    return 0;
}

